var factory = new ConnectionFactory() { HostName = "localhost" };
using var connection = factory.CreateConnection();
using var channel = connection.CreateModel();

// Declare direct exchange
channel.ExchangeDeclare("app.logs", ExchangeType.Direct, durable: true);

// Declare queues
channel.QueueDeclare("error-alerts", durable: true);
channel.QueueDeclare("warning-dashboard", durable: true);
channel.QueueDeclare("info-archive", durable: true);

// Bind each queue with its specific routing key
channel.QueueBind(queue: "error-alerts", exchange: "app.logs", routingKey: "error");
channel.QueueBind(queue: "warning-dashboard", exchange: "app.logs", routingKey: "warning");
channel.QueueBind(queue: "info-archive", exchange: "app.logs", routingKey: "info");

// Publish an error message
var body = Encoding.UTF8.GetBytes("Disk full on /dev/sda1");
channel.BasicPublish(
    exchange: "app.logs",
    routingKey: "error",
    basicProperties: null,
    body: body);

const amqp = require('amqplib');

async function startErrorConsumer() {
  const conn = await amqp.connect('amqp://localhost');
  const ch = await conn.createChannel();

  await ch.assertExchange('app.logs', 'direct', { durable: true });
  await ch.assertQueue('error-alerts', { durable: true });

  // Bind only to the 'error' routing key
  ch.bindQueue('error-alerts', 'app.logs', 'error');

  ch.consume('error-alerts', (msg) => {
    if (msg.content) {
      const severity = msg.fields.routingKey;
      const text = msg.content.toString();
      console.log(`[${severity}] ${text}`);
    }
  });
}

startErrorConsumer();
